first_field_self_reference.source:
using symbol "std:io" @print;
regional type Node { next::ref<Node>; value::i64; }
symbol @arena;
symbol @node;
effect @arena = region(128u64);
effect @node = alloc @arena Node(null, 7);
setfield(@node, next, @node);
behave @print(deref(@node).next == @node);
behave @print(deref(@node).next == null);
